import Vue from 'vue';
import { Component, Prop } from 'vue-property-decorator';
import { IServerErrorsTranslations } from '../../../../types';
import { IErrorState } from '../../types';

@Component({})
export default class ErrorInformation extends Vue {
    @Prop()
    protected state: IErrorState;

    @Prop()
    protected translations: IServerErrorsTranslations;

    constructor() {
        super();
        for (const error of this.state.errors) {
            error.description = this.translations[this.state.errorCode][error.name] ||
                this.translations[0].Generic;
        }
    }
}
